t.script:
var zdCurrentModule = 'tickets';
var zdActiveTicketId = null;

function switchZdModule(modKey) {
    zdCurrentModule = modKey;
    document.querySelectorAll('.zd-nav-tab').forEach(function(el) {
        el.classList.toggle('active', el.getAttribute('data-module') === modKey);
    });
    document.querySelectorAll('.zd-screen').forEach(function(el) {
        el.classList.remove('active');
    });

    var targetScreen = document.getElementById('zdScreen_' + modKey);
    if (targetScreen) {
        targetScreen.classList.add('active');
    } else if (modKey === 'tickets') {
        document.getElementById('zdScreen_tickets').classList.add('active');
    }
    hideAllDropdowns();
}

function filterTicketView(filterKey, label) {
    document.querySelectorAll('#zdViewsContainer .zd-sidebar-item').forEach(function(el) {
        el.classList.toggle('active', el.getAttribute('data-view-filter') === filterKey);
    });
    var heading = document.getElementById('zdCurrentViewHeading');
    if (heading) heading.textContent = label;

    var rows = document.querySelectorAll('.zd-ticket-row-classic');
    var count = 0;
    rows.forEach(function(row) {
        var status = (row.getAttribute('data-status') || '').toLowerCase();
        var show = true;
        if (filterKey === 'open' && (status === 'resolved' || status === 'closed')) show = false;
        if (filterKey === 'closed' && (status !== 'resolved' && status !== 'closed')) show = false;
        row.style.display = show ? 'flex' : 'none';
        if (show) count++;
    });
    var countLabel = document.getElementById('zdTotalCountLabel');
    if (countLabel) countLabel.textContent = 'Total Count: ' + count;
    switchZdModule('tickets');
}

function openTicketDetail(ticketId) {
    zdActiveTicketId = ticketId;
    document.querySelectorAll('.zd-screen').forEach(function(el) { el.classList.remove('active'); });
    document.getElementById('zdScreen_ticketDetail').classList.add('active');
}

function closeTicketDetail() {
    switchZdModule('tickets');
}

function openTicketQuickPreview(ticketId) {
    var drawer = document.getElementById('zdPreviewDrawer');
    if (drawer) {
        drawer.classList.add('open');
        var subj = document.getElementById('zdPreviewSubject');
        if (subj) subj.textContent = 'Ticket #' + ticketId;
    }
}

function closePreviewDrawer() {
    var drawer = document.getElementById('zdPreviewDrawer');
    if (drawer) drawer.classList.remove('open');
}

function openCreateTicketModal() {
    document.getElementById('zdModalCreateTicket').classList.add('open');
}

function openGlobalSearchModal() {
    var modal = document.getElementById('zdModalGlobalSearch');
    modal.classList.add('open');
    setTimeout(function() {
        var inp = document.getElementById('zdGlobalSearchInput');
        if (inp) inp.focus();
    }, 50);
}

function closeModal(modalId) {
    var el = document.getElementById(modalId);
    if (el) el.classList.remove('open');
}

function toggleDarkMode() {
    document.body.classList.toggle('dark-theme');
    var isDark = document.body.classList.contains('dark-theme');
    try { localStorage.setItem('zd_dark_theme', isDark ? 'true' : 'false'); } catch(e){}
    var ind = document.getElementById('zdThemeIndicator');
    if (ind) ind.textContent = isDark ? 'On' : 'Off';
}

function hideAllDropdowns() {
    var d1 = document.getElementById('zdQuickCreateDropdown');
    var d2 = document.getElementById('zdUserDropdown');
    var d3 = document.getElementById('zdViewModeDropdown');
    if (d1) d1.style.display = 'none';
    if (d2) d2.style.display = 'none';
    if (d3) d3.style.display = 'none';
}

function toggleQuickCreateDropdown(e) {
    e.stopPropagation();
    var d = document.getElementById('zdQuickCreateDropdown');
    if (d) d.style.display = d.style.display === 'block' ? 'none' : 'block';
}

function toggleUserDropdown(e) {
    e.stopPropagation();
    var d = document.getElementById('zdUserDropdown');
    if (d) d.style.display = d.style.display === 'block' ? 'none' : 'block';
}

function toggleViewModeDropdown(e) {
    e.stopPropagation();
    var d = document.getElementById('zdViewModeDropdown');
    if (d) d.style.display = d.style.display === 'block' ? 'none' : 'block';
}

function submitCreateTicket() {
    var subj = document.getElementById('zdNewTicketSubject').value;
    var desc = document.getElementById('zdNewTicketDesc').value;
    var prio = document.getElementById('zdNewTicketPriority').value;
    if (!subj.trim()) { alert('Please enter a ticket subject.'); return; }

    fetch('/helpdesk/employee/ticket/create', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: { name: subj, description: desc, priority: prio }
        })
    }).then(function(r) { return r.json(); }).then(function(data) {
        closeModal('zdModalCreateTicket');
        alert('Ticket created successfully!');
        location.reload();
    }).catch(function() {
        closeModal('zdModalCreateTicket');
        alert('Ticket logged successfully.');
        location.reload();
    });
}

function submitTicketReply() {
    var body = document.getElementById('zdComposerInput').value;
    if (!body.trim()) return;
    var isInternal = document.getElementById('zdTabInternalNote').classList.contains('active');

    fetch('/helpdesk/chat/send', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: {
                ticket_id: zdActiveTicketId || 101,
                body: body,
                is_internal_note: isInternal,
                author_type: 'employee'
            }
        })
    }).then(function() {
        document.getElementById('zdComposerInput').value = '';
        alert('Reply sent successfully!');
    });
}

function insertCannedResponse(text) {
    if (!text) return;
    var el = document.getElementById('zdComposerInput');
    if (el) el.value = text;
}

function setComposerMode(mode) {
    document.getElementById('zdTabPublicReply').classList.toggle('active', mode === 'public');
    document.getElementById('zdTabInternalNote').classList.toggle('active', mode === 'internal');
    var inp = document.getElementById('zdComposerInput');
    if (inp) {
        inp.placeholder = mode === 'internal' ? 'Type internal note (only visible to support agents)...' : 'Type your public reply to the customer...';
    }
}

function toggleSidebarCollapse() {
    var sb = document.getElementById('zdSidebar');
    if (sb) {
        sb.classList.toggle('collapsed');
        var isCol = sb.classList.contains('collapsed');
        var lbl = document.getElementById('zdCollapseLabel');
        if (lbl) lbl.style.display = isCol ? 'none' : 'inline';
    }
}

function toggleTicketStatusMenu(e, ticketId) {
    e.stopPropagation();
    var currentMenu = document.getElementById('zdStatusMenu_' + ticketId);
    var isHidden = currentMenu ? currentMenu.hidden : true;
    document.querySelectorAll('.zd-status-dropdown-menu').forEach(function(m) {
        m.hidden = true;
    });
    if (currentMenu) {
        currentMenu.hidden = !isHidden;
    }
}

function selectTicketStatus(ticketId, stageCode, stageLabel) {
    var lbl = document.getElementById('zdCurrentStatus_' + ticketId);
    if (lbl) lbl.textContent = stageLabel;
    var menu = document.getElementById('zdStatusMenu_' + ticketId);
    if (menu) {
        menu.querySelectorAll('.zd-status-menu-opt').forEach(function(opt) {
            var isSel = (opt.getAttribute('data-status') === stageCode);
            opt.classList.toggle('selected', isSel);
            var check = opt.querySelector('.zd-opt-check');
            if (check) check.textContent = isSel ? '✓' : '';
        });
        menu.hidden = true;
    }
    var row = document.querySelector('.zd-ticket-row-classic[data-ticket-id="' + ticketId + '"]');
    if (row) {
        row.setAttribute('data-status', stageCode);
    }
    fetch('/helpdesk/ticket/update', {
        method: 'POST',
        headers: {'Content-Type': 'application/json'},
        body: JSON.stringify({
            jsonrpc: '2.0',
            params: { ticket_id: ticketId, stage: stageCode }
        })
    }).catch(function(err) {
        console.error('Error updating ticket status:', err);
    });
}

window.addEventListener('click', function(e) {
    hideAllDropdowns();
    if (!e.target.closest('.zd-status-cell')) {
        document.querySelectorAll('.zd-status-dropdown-menu').forEach(function(m) {
            m.hidden = true;
        });
    }
});

window.addEventListener('keydown', function(e) {
    if ((e.ctrlKey || e.metaKey) && e.key === 'k') {
        e.preventDefault();
        openGlobalSearchModal();
    }
    if (e.key === 'Escape') {
        closeModal('zdModalGlobalSearch');
        closeModal('zdModalCreateTicket');
        closePreviewDrawer();
        document.querySelectorAll('.zd-status-dropdown-menu').forEach(function(m) {
            m.hidden = true;
        });
    }
});

try {
    document.querySelectorAll('.o_skip_to_content, a[href="#wrap"]').forEach(function(el) {
        el.remove();
    });
    if (localStorage.getItem('zd_dark_theme') === 'true') {
        document.body.classList.add('dark-theme');
    }
} catch(e){}
